#include <cstdlib>
#include <fstream>
#include <iostream>
#include <string>
#include <vector>
using namespace std;

static bool existsPattern(const vector<string>& g) {
    const vector<string> pat = {"0000", "0110", "0110", "0000"};
    int n = g.size(), m = g[0].size();
    for (int i = 0; i + 4 <= n; ++i)
        for (int j = 0; j + 4 <= m; ++j) {
            bool ok = true;
            for (int r = 0; r < 4 && ok; ++r)
                for (int c = 0; c < 4; ++c)
                    if (g[i + r][j + c] != pat[r][c]) { ok = false; break; }
            if (ok) return true;
        }
    return false;
}
static bool check(const string& exe, const vector<vector<string>>& cases, int id) {
    const string inF = "l4a09p1_in.txt", outF = "l4a09p1_out.txt";
    {
        ofstream o(inF);
        o << cases.size() << '\n';
        for (size_t t = 0; t < cases.size(); ++t) {
            const vector<string>& g = cases[t];
            o << g.size() << ' ' << g[0].size() << '\n';
            for (size_t i = 0; i < g.size(); ++i) o << g[i] << '\n';
        }
    }
    int code = system(("\"" + exe + "\" < " + inF + " > " + outF + " 2>/dev/null").c_str());
    vector<string> got, want;
    {
        ifstream in(outF);
        string line;
        while (getline(in, line)) {
            if (!line.empty() && line.back() == '\r') line.pop_back();
            got.push_back(line);
        }
    }
    for (size_t t = 0; t < cases.size(); ++t)
        want.push_back(existsPattern(cases[t]) ? "Yes" : "No");
    if (code != 0 || got != want) {
        cout << "[FAIL] case " << id << ": expected ";
        for (size_t i = 0; i < want.size(); ++i) cout << want[i] << ' ';
        cout << ", actual: ";
        for (size_t i = 0; i < got.size(); ++i) cout << got[i] << ' ';
        cout << ", status=" << code << '\n';
        return false;
    }
    return true;
}
static vector<string> randGrid(int n, int m, unsigned seed) {
    srand(seed);
    vector<string> g;
    for (int i = 0; i < n; ++i) {
        string s;
        for (int j = 0; j < m; ++j) s += (rand() % 2) ? '1' : '0';
        g.push_back(s);
    }
    return g;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    int passed = 0, total = 0;
    vector<vector<string>> c1 = {
        vector<string>{"0110"},
        vector<string>{"00000", "01100", "01100", "00001", "01100"},
        vector<string>{"00000", "01100", "01110", "00001", "01100"}
    };
    ++total; if (check(exe, c1, 1)) ++passed;  // 样例1
    vector<vector<string>> c2;
    c2.push_back(vector<string>{"0000", "0110", "0110", "0000"});          // 恰好命中
    c2.push_back(vector<string>{"0000", "0110", "0110", "0001"});          // 差一格
    c2.push_back(vector<string>{"1111", "1111", "1111", "1111"});          // 全黑
    c2.push_back(vector<string>{"0000", "0110", "0110", "0000", "01100", "01100", "00001"});  // 5x5 偏移处命中
    c2.push_back(vector<string>{"0", "0", "0", "0"});                      // 4x1 放不下
    c2.push_back(vector<string>{"00000"});                                 // 1x5 放不下
    ++total; if (check(exe, c2, 2)) ++passed;  // 边界
    vector<vector<string>> c3;
    c3.push_back(randGrid(100, 100, 20240901));
    c3.push_back(randGrid(3, 100, 20240902));
    c3.push_back(randGrid(100, 3, 20240903));
    c3.push_back(randGrid(7, 7, 20240904));
    ++total; if (check(exe, c3, 3)) ++passed;  // 较大与随机
    cout << "Results: " << passed << "/" << total << " passed" << '\n';
    return passed == total ? 0 : 1;
}

