             << ", actual=" << got.substr(0, 200) << ", status=" << code << '\n';
        return false;
    }
    return true;
}
int main(int argc, char* argv[]) {
    if (argc < 2) return 2;
    const string exe = argv[1];
    int passed = 0, total = 0;
    ++total; if (check(exe, {3, 4, 5, 2, 1}, {{4, 5}, {3, 4}, {1, 3}}, 1)) ++passed;  // 样例1
